void reset(int *arr, int size) {
    int i;
    for (i=0; i<size; i+=1)
      arr[i]= 1;
}
void print(int *arr, int size) {
    int i;
    for (i=0; i<size; i+=1)
      printf("%d", arr[i]);
}
int main(void) {
  int arr[5] = {1, 2, 3, 4, 0};
  reset(arr, 3);
  print(arr, 5);
  return 0;
}

